import Image from "next/image";
import { Activity, Bot, Database, Globe, Server, Workflow, type LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";

/**
 * Hero illustration (DA v3.1): an isometric architecture diagram generated by
 * `scripts/gen-hero-iso.py` (api = cobalt, agents = pink, web = lime, data = green, CI/CD = yellow,
 * observability = sky), labelled with square chips, plus a terminal "ship log" card. Anchors are
 * the % printed by the generator: re-run it and copy them here if the scene changes.
 */
const RATIO = "1038.4 / 648";

type Chip = { left: number; top: number; icon: LucideIcon; label: string; live?: boolean };

const CHIPS: Chip[] = [
  { left: 46.5, top: 42.4, icon: Server, label: "api", live: true },
  { left: 74.0, top: 51.2, icon: Bot, label: "agents", live: true },
  { left: 52.0, top: 21.6, icon: Globe, label: "web", live: true },
  { left: 35.0, top: 61.4, icon: Database, label: "data" },
  { left: 26.0, top: 38.3, icon: Workflow, label: "ci/cd", live: true },
  { left: 58.0, top: 57.7, icon: Activity, label: "obs" },
];
const PIERRE = { left: 54.0, top: 42.9 };

function LabelChip({ chip }: { chip: Chip }) {
  const Icon = chip.icon;
  return (
    <span
      className="absolute inline-flex -translate-x-1/2 -translate-y-[115%] items-center gap-1.5 border border-foreground/10 bg-card px-1.5 py-1 font-mono text-[10px] text-foreground/85 shadow-sm sm:text-[11px]"
      style={{ left: `${chip.left}%`, top: `${chip.top}%` }}
    >
      <Icon className="size-3 sm:size-3.5" strokeWidth={1.75} />
      <span className="hidden sm:inline">{chip.label}</span>
      {chip.live ? <span className="size-1.5 bg-shape-green" /> : null}
    </span>
  );
}

// What Pierre ships right now (facts from the case studies; statuses as on the site).
const SHIPPING = [
  { id: "taskforce", status: "live", glyph: "✓", tone: "text-shape-lime" },
  { id: "brain-os", status: "r&d", glyph: "↻", tone: "text-shape-sky" },
  { id: "plania", status: "leading", glyph: "●", tone: "text-shape-yellow" },
  { id: "safex-agent", status: "in production", glyph: "✓", tone: "text-shape-lime" },
] as const;

function ShipLog({ className }: { className?: string }) {
  return (
    <div className={cn("w-[20rem] border border-night-line bg-night text-night-foreground shadow-xl", className)}>
      <div className="flex h-8 items-center gap-1.5 border-b border-night-line px-3">
        <span className="size-2 bg-shape-red" />
        <span className="size-2 bg-shape-yellow" />
        <span className="size-2 bg-shape-green" />
        <span className="ml-2 font-mono text-[11px] text-night-muted">~/pierre/ship.log</span>
      </div>
      <div className="space-y-1.5 px-4 py-3.5 font-mono text-[12px] leading-relaxed">
        <p className="text-night-muted">$ ship --status</p>
        {SHIPPING.map((s) => (
          <p key={s.id} className="flex items-center justify-between gap-4">
            <span>
              <span className={s.tone}>{s.glyph}</span> {s.id}
            </span>
            <span className="text-night-muted">{s.status}</span>
          </p>
        ))}
        <p className="pt-1">
          <span className="text-shape-lime">&gt;</span> next: your project
          <span aria-hidden className="ml-1 inline-block h-3.5 w-2 translate-y-0.5 animate-blink bg-shape-lime" />
        </p>
      </div>
    </div>
  );
}

export function HeroIso({ className }: { className?: string }) {
  return (
    <div className={cn("relative", className)}>
      <div className="relative w-full" style={{ aspectRatio: RATIO }}>
        {/* one SVG per theme (walls and floor differ, block tops are identical) */}
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src="/illustrations/hero-iso.svg"
          alt="An isometric architecture diagram: api, agents, web, data, CI/CD and observability blocks wired together"
          className="absolute inset-0 size-full select-none dark:hidden"
          draggable={false}
        />
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src="/illustrations/hero-iso-dark.svg"
          alt=""
          aria-hidden="true"
          className="absolute inset-0 hidden size-full select-none dark:block"
          draggable={false}
        />
        <div aria-hidden="true">
          {CHIPS.map((c) => (
            <LabelChip key={c.label} chip={c} />
          ))}
          {/* Pierre, on the api block */}
          <span className="absolute -translate-x-1/2 -translate-y-full" style={{ left: `${PIERRE.left}%`, top: `${PIERRE.top}%` }}>
            <span className="relative block size-8 overflow-hidden border-2 border-card shadow-lg sm:size-11">
              <Image src="/images/avatar.png" alt="" fill sizes="44px" className="object-cover" priority />
            </span>
            <span className="absolute -bottom-1 -right-1 size-3 border-2 border-card bg-shape-green" />
          </span>
        </div>
      </div>
      <ShipLog className="animate-float absolute right-[2%] top-[-10%] hidden sm:block" />
    </div>
  );
}
